import{_ as l,a0 as p,w as n,s as o,ao as d,I as s,x as e,a1 as t,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"用 Spark SQL 進行結構化數據處理 | LCTT x X-CMD","titleTemplate":false,"description":"用 Spark SQL 進行結構化數據處理 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Spark SQL 進行結構化數據處理 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Spark SQL 進行結構化數據處理 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220516 Structured Data Processing with Spark SQL","title":"用 Spark SQL 進行結構化數據處理","tag":"202205","desc":""},"relativePath":"202205/20220516 Structured Data Processing with Spark SQL.md","filePath":"[post].md"}'),h={name:"202205/20220516 Structured Data Processing with Spark SQL.md"};function k(u,a,S,c,b,g){const r=p("Link");return n(),o("div",null,[a[15]||(a[15]=d('<h1 id="用-spark-sql-進行結構化數據處理" tabindex="-1">用 Spark SQL 進行結構化數據處理 <a class="header-anchor" href="#用-spark-sql-進行結構化數據處理" aria-label="Permalink to “用 Spark SQL 進行結構化數據處理”">​</a></h1><blockquote><p>Spark SQL 是 Spark 生態系統中處理結構化格式數據的模組。它在內部使用 Spark Core API 進行處理，但對用户的使用進行了抽象。這篇文章深入淺出地告訴你 Spark SQL 3.x 的新內容。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202205/24/093036xaf6kaz1auaf4a7s.jpg" alt=""></p><p>有了 Spark SQL，用户可以編寫 SQL 風格的查詢。這對於精通結構化查詢語言或 SQL 的廣大用户羣體來説，基本上是很有幫助的。用户也將能夠在結構化數據上編寫交互式和臨時性的查詢。Spark SQL 彌補了<ruby>彈性分佈式數據集<rt>resilient distributed data sets</rt></ruby>（RDD）和關係表之間的差距。RDD 是 Spark 的基本數據結構。它將數據作為分佈式對象存儲在適合並行處理的節點集羣中。RDD 很適合底層處理，但在運行時很難調試，程序員不能自動推斷<ruby>模式<rt>schema</rt></ruby>。另外，RDD 沒有內置的優化功能。Spark SQL 提供了<ruby>數據幀<rt>DataFrame</rt></ruby>和數據集來解決這些問題。</p><p>Spark SQL 可以使用現有的 Hive 元存儲、SerDes 和 UDF。它可以使用 JDBC/ODBC 連接到現有的 BI 工具。</p><h3 id="數據源" tabindex="-1">數據源 <a class="header-anchor" href="#數據源" aria-label="Permalink to “數據源”">​</a></h3><p>大數據處理通常需要處理不同的文件類型和數據源（關係型和非關係型）的能力。Spark SQL 支持一個統一的數據幀接口來處理不同類型的源，如下所示。</p><ul><li>文件： <ul><li>CSV</li><li>Text</li><li>JSON</li><li>XML</li></ul></li><li>JDBC/ODBC： <ul><li>MySQL</li><li>Oracle</li><li>Postgres</li></ul></li><li>帶模式的文件： <ul><li>AVRO</li><li>Parquet</li></ul></li><li>Hive 表： <ul><li>Spark SQL 也支持讀寫存儲在 Apache Hive 中的數據。</li></ul></li></ul><p>通過數據幀，用户可以無縫地讀取這些多樣化的數據源，並對其進行轉換/連接。</p><h3 id="spark-sql-3-x-的新內容" tabindex="-1">Spark SQL 3.x 的新內容 <a class="header-anchor" href="#spark-sql-3-x-的新內容" aria-label="Permalink to “Spark SQL 3.x 的新內容”">​</a></h3><p>在以前的版本中（Spark 2.x），查詢計劃是基於啓發式規則和成本估算的。從解析到邏輯和物理查詢計劃，最後到優化的過程是連續的。這些版本對轉換和行動的運行時特性幾乎沒有可見性。因此，由於以下原因，查詢計劃是次優的：</p><ul><li>缺失和過時的統計數據</li><li>次優的啓發式方法</li><li>錯誤的成本估計</li></ul><p>Spark 3.x 通過使用運行時數據來迭代改進查詢計劃和優化，增強了這個過程。前一階段的運行時統計數據被用來優化後續階段的查詢計劃。這裏有一個反饋迴路，有助於重新規劃和重新優化執行計劃。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-1-Query-planning.jpg" alt="Figure 1: Query planning"></p><h4 id="自適應查詢執行-aqe" tabindex="-1">自適應查詢執行（AQE） <a class="header-anchor" href="#自適應查詢執行-aqe" aria-label="Permalink to “自適應查詢執行（AQE）”">​</a></h4><p>查詢被改變為邏輯計劃，最後變成物理計劃。這裏的概念是“重新優化”。它利用前一階段的可用數據，為後續階段重新優化。正因為如此，整個查詢的執行要快得多。</p><p>AQE 可以通過設置 SQL 配置來啓用，如下所示（Spark 3.0 中默認為 false）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>spark.conf.set(“spark.sql.adaptive.enabled”,true)</span></span></code></pre></div><h4 id="動態合併-洗牌-分區" tabindex="-1">動態合併“洗牌”分區 <a class="header-anchor" href="#動態合併-洗牌-分區" aria-label="Permalink to “動態合併“洗牌”分區”">​</a></h4><p>Spark 在“<ruby>洗牌<rt>shuffle</rt></ruby>”操作後確定最佳的分區數量。在 AQE 中，Spark 使用默認的分區數，即 200 個。這可以通過配置來啓用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>spark.conf.set(“spark.sql.adaptive.coalescePartitions.enabled”,true)</span></span></code></pre></div><h4 id="動態切換連接策略" tabindex="-1">動態切換連接策略 <a class="header-anchor" href="#動態切換連接策略" aria-label="Permalink to “動態切換連接策略”">​</a></h4><p>廣播哈希是最好的連接操作。如果其中一個數據集很小，Spark 可以動態地切換到廣播連接，而不是在網絡上“洗牌”大量的數據。</p><h4 id="動態優化傾斜連接" tabindex="-1">動態優化傾斜連接 <a class="header-anchor" href="#動態優化傾斜連接" aria-label="Permalink to “動態優化傾斜連接”">​</a></h4><p>如果數據分佈不均勻，數據會出現傾斜，會有一些大的分區。這些分區佔用了大量的時間。Spark 3.x 通過將大分區分割成多個小分區來進行優化。這可以通過設置來啓用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>spark.conf.set(“spark.sql.adaptive.skewJoin.enabled”,true)</span></span></code></pre></div><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-2-Performance-improvement-in-Spark-3.x-Source-Databricks.jpg" alt="Figure 2: Performance improvement in Spark 3.x (Source: Databricks)"></p><h3 id="其他改進措施" tabindex="-1">其他改進措施 <a class="header-anchor" href="#其他改進措施" aria-label="Permalink to “其他改進措施”">​</a></h3><p>此外，Spark SQL 3.x還支持以下內容。</p><h4 id="動態分區修剪" tabindex="-1">動態分區修剪 <a class="header-anchor" href="#動態分區修剪" aria-label="Permalink to “動態分區修剪”">​</a></h4><p>3.x 將只讀取基於其中一個表的值的相關分區。這消除了解析大表的需要。</p><h4 id="連接提示" tabindex="-1">連接提示 <a class="header-anchor" href="#連接提示" aria-label="Permalink to “連接提示”">​</a></h4><p>如果用户對數據有了解，這允許用户指定要使用的連接策略。這增強了查詢的執行過程。</p><h4 id="兼容-ansi-sql" tabindex="-1">兼容 ANSI SQL <a class="header-anchor" href="#兼容-ansi-sql" aria-label="Permalink to “兼容 ANSI SQL”">​</a></h4><p>在兼容 Hive 的早期版本的 Spark 中，我們可以在查詢中使用某些關鍵詞，這樣做是完全可行的。然而，這在 Spark SQL 3 中是不允許的，因為它有完整的 ANSI SQL 支持。例如，“將字符串轉換為整數”會在運行時產生異常。它還支持保留關鍵字。</p><h4 id="較新的-hadoop、java-和-scala-版本" tabindex="-1">較新的 Hadoop、Java 和 Scala 版本 <a class="header-anchor" href="#較新的-hadoop、java-和-scala-版本" aria-label="Permalink to “較新的 Hadoop、Java 和 Scala 版本”">​</a></h4><p>從 Spark 3.0 開始，支持 Java 11 和 Scala 2.12。 Java 11 具有更好的原生協調和垃圾校正，從而帶來更好的性能。 Scala 2.12 利用了 Java 8 的新特性，優於 2.11。</p><p>Spark 3.x 提供了這些現成的有用功能，而無需開發人員操心。這將顯着提高 Spark 的整體性能。</p><hr>',39)),s("p",null,[a[1]||(a[1]=e("via: ",-1)),t(r,{href:"https://www.opensourceforu.com/2022/05/structured-data-processing-with-spark-sql/"},{default:i(()=>[...a[0]||(a[0]=[e("https://www.opensourceforu.com/2022/05/structured-data-processing-with-spark-sql/",-1)])]),_:1})]),s("p",null,[a[6]||(a[6]=e("作者：",-1)),t(r,{href:"https://www.opensourceforu.com/author/phani-kiran/"},{default:i(()=>[...a[2]||(a[2]=[e("Phani Kiran",-1)])]),_:1}),a[7]||(a[7]=e(" 選題：",-1)),t(r,{href:"https://github.com/lkxed"},{default:i(()=>[...a[3]||(a[3]=[e("lkxed",-1)])]),_:1}),a[8]||(a[8]=e(" 譯者：",-1)),t(r,{href:"https://github.com/geekpi"},{default:i(()=>[...a[4]||(a[4]=[e("geekpi",-1)])]),_:1}),a[9]||(a[9]=e(" 校對：",-1)),t(r,{href:"https://github.com/wxy"},{default:i(()=>[...a[5]||(a[5]=[e("wxy",-1)])]),_:1})]),s("p",null,[a[12]||(a[12]=e("本文由 ",-1)),t(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[10]||(a[10]=[e("LCTT",-1)])]),_:1}),a[13]||(a[13]=e(" 原創編譯，",-1)),t(r,{href:"https://linux.cn/"},{default:i(()=>[...a[11]||(a[11]=[e("Linux中國",-1)])]),_:1}),a[14]||(a[14]=e(" 榮譽推出",-1))])])}const L=l(h,[["render",k]]);export{x as __pageData,L as default};
